insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللَّهِ بْنِ عَدِيِّ بْنِ حَمْرَاءَ الزُّهْرِيِّ.رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاقِفًا عَلَى الْحَزْوَرَةِ، فَقَالَ: "وَاللَّهِ، إِنَّكَ لَخَيْرُ أَرْضِ اللَّهِ، وَأَحَبُّ أَرْضِ اللَّهِ إِلَى اللَّهِ، وَلَوْلَا أَنِّي أُخْرِجْتُ مِنْك مَا خَرَجْتُ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അദിയ്യുബ്നു ഹംറാഉസ്സുഹ്രി(റ): റസൂൽ(സ) ഹസ്വറ എന്ന സ്ഥലത്ത് നിൽക്കുന്നത് ഞാൻ കണ്ടു. അവിടുന്ന് ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവാണ, നിശ്ചയം നീ (മക്ക) അല്ലാഹുവിന്റെ ഭൂമിയിൽ ഏറ്റവും ഉത്തമമായ സ്ഥലമാണ്. അല്ലാഹുവിന്റെ ഭൂമിയിൽ അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടതുമാണ് നീ. നിന്നിൽനിന്ന് ഞാൻ പുറത്താക്കപ്പെട്ടില്ലായിരുന്നുവെങ്കിൽ ഞാൻ പുറത്ത് പോകുമായിരുന്നില്ല." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَدِيِّ بْنِ حَمْرَاءَ الزُّهْرِيِّ.', 'അബ്ദുല്ലാഹിബ്നു അദിയ്യുബ്നു ഹംറാഉസ്സുഹ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي الطُّفَيْلِ، عَنِ ابْنِ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمْ – قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَكَّةَ: "مَا أَطْيَبَكِ مِنْ بَلَدٍ وَأَحَبَّكِ إِلَيَّ، وَلَوْلَا أَنَّ قَوْمِي أَخْرَجُونِي مِنْكِ مَا سَكَنْتُ غَيْرَكِ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ)വിൽനിന്ന് അബുത്ത്വുഫൈൽ(റ): റസൂൽ(സ) മക്കയോടായി പറഞ്ഞു: "എത്ര സുന്ദരവും എനിക്ക് എത്ര പ്രിയപ്പെട്ടതുമായ നാടാണ് നീ. എന്റെ സമൂഹം നിന്നിൽനിന്ന് എന്നെ പുറത്താക്കിയിട്ടില്ലായിരുന്നുവെങ്കിൽ നീയല്ലാത്തൊരു നാട്ടിലും ഞാൻ താമസിക്കുമായിരുന്നില്ല." (തു)', 'أَبِي الطُّفَيْلِ، عَنِ ابْنِ عَبَّاسٍ –', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "احْتِكَارُ الطَّعَامِ فِي الْحَرَمِ إِلْحَادٌ فِيهِ". (د)', 'യഅ്ലബ്നു ഉമയ്യ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഹറമിൽ ഭക്ഷണം പൂഴ്തിവെക്കൽ (വിലകൂടുതൽ ലഭിക്കുന്ന കാലത്തേക്കുവേണ്ടി ആവശ്യവസ്തക്കൾ പൂഴ്തിവെക്കൽ) അതിനോടുള്ള അവിശ്വാസമാണ്." (ദ)', 'يَعْلَى بْنِ أُمَيَّةَ', 'യഅ്ലബ്നു ഉമയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ صَفِيَّةَ بِنْت شَيْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَامَ الْفَتْحِ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّ اللَّهَ حَرَّمَ مَكَّةَ يَوْمَ خَلَقَ السَّمٰوَاتِ وَالْأَرْضَ، فَهِيَ حَرَامٌ إِلَى يَوْمِ الْقِيَامَةِ، لَا يُعْضَدُ شَجَرُهَا، وَلَا يُنَفَّرُ صَيْدُهَا وَلَا يَأْخُذُ لُقَطَتَهَا إِلَّا مُنْشِدٌ". فَقَالَ الْعَبَّاسُ رَضِيَ اللهُ عَنْهُ: إِلَّا الْإِذْخِرَ، فَإِنَّهُ لِلْبُيُوتِ وَالْقُبُورِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِلَّا الْإِذْخِرَ". (خ,جه)', 'സ്വഫിയ്യതു ബിൻതുശൈബ(റ): ഫത്ഹുമക്കയുടെ വർഷം റസൂൽ(സ) ഇപ്രകാരം പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടു: "ജനങ്ങളേ, നിശ്ചയം ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിച്ച ദിനത്തിൽ അല്ലാഹു മക്കയെ പവിത്രമായി പ്രഖ്യാപിച്ചു. അത് അന്ത്യനാൾവരെ പവിത്രമായതാണ്. അതിലെ മരങ്ങൾ മുറിക്കപ്പെടുകയോ വേട്ടമൃഗങ്ങളെ പിന്തുടരുകയോ അതിൽവെച്ച് വീണുകിട്ടിയത് എടുക്കപ്പെടുകയോ ചെയ്യാൻ പാടില്ല, വീണുകിട്ടിയ വസ്തുവിനെക്കുറിച്ച് വിവരം നൽകുന്നവനൊഴികെ." അപ്പോൾ അബ്ബാസ്(റ) പറഞ്ഞു: ഇദ്ഖിർ ചെടി (സുഗന്ധമുള്ള ഒരു പുല്ല്) ഒഴികെ. നിശ്ചയം വീടുകൾക്കും ഖബറുകൾക്കുംവേണ്ടി അത് ഉപയോഗിക്കാറുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇദ്ഖിർ ചെടിയൊഴികെ." (ബു,ജ)', 'صَفِيَّةَ بِنْت شَيْبَةَ', 'സ്വഫിയ്യതു ബിൻതുശൈബ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 515, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ الْمَخْزُومِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ هَذِهِ الْأُمَّةُ بِخَيْرٍ مَا عَظَّمُوا هَذِهِ الْحُرْمَةَ حَقَّ تَعْظِيمِهَا، فَإِذَا ضَيَّعُوا ذَلِكَ هَلَكُوا". (جه)', 'അയ്യാശുബ്നു അബീറബീഅതൽ മഖ്സൂമി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ പവിത്രതയെ (മക്കയുടെ പവിത്രത) വേണ്ടവിധം ബഹുമാനിക്കുന്ന കാലത്തോളം ഈ സമുദായം നന്മയിലായിരിക്കും. അതിനെ നഷ്ടപ്പെടുത്തിയാൽ അവർ നശിക്കും." (ജ)', 'عَيَّاشِ بْنِ أَبِي رَبِيعَةَ الْمَخْزُومِيِّ', 'അയ്യാശുബ്നു അബീറബീഅതൽ മഖ്സൂമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَدْرَكَ رَمَضَانَ بِمَكَّةَ فَصَامَ، وَقَامَ مِنْهُ مَا تَيَسَّرَ لَهُ، كَتَبَ اللَّهُ لَهُ مِائَةَ أَلْفِ شَهْرِ رَمَضَانَ فِيمَا سِوَاهَا، وَكَتَبَ اللَّهُ لَهُ بِكُلِّ يَوْمٍ عِتْقَ رَقَبَةٍ، وَكُلِّ لَيْلَةٍ عِتْقَ رَقَبَةٍ، وَكُلِّ يَوْمٍ حُمْلَانَ فَرَسٍ فِي سَبِيلِ اللَّهِ، وَفِي كُلِّ يَوْمٍ حَسَنَةً، وَفِي كُلِّ لَيْلَةٍ حَسَنَةً". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് മക്കയിൽവെച്ച് റമളാൻ സമാഗതമാവുകയും അങ്ങനെ അവൻ നോമ്പനുഷ്ഠിക്കുകയും കഴിയുംവിധം റമളാനിൽ നമസ്കരിക്കുകയും ചെയ്താൽ മക്കയല്ലാത്ത നാട്ടിൽവെച്ചുള്ള ഒരു ലക്ഷം റമളാൻ മാസത്തിന്റെ പുണ്യം അല്ലാഹു അവന് രേഖപ്പെടുത്തുന്നതാണ്. ഓരോ പകലിനും ഓരോ അടിമയെ മോചിപ്പിച്ച പുണ്യവും, ഓരോ രാത്രിക്കും ഓരോ അടിമയെ മോചിപ്പിച്ച പുണ്യവും, ഓരോ ദിവസത്തിനും ഒരു കുതിരക്ക് വഹിക്കാനുള്ളയത്ര മുതൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ദാനംചെയ്ത പുണ്യവും, ഓരോ പകലിനും ഒരു നന്മയും, ഓരോ രാത്രിക്കും ഓരോ നന്മയും അല്ലാഹു അവന് രേഖപ്പെടുത്തുന്നതാണ്." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ، إِلَّا رَدَّ اللَّهُ عَلَيَّ رُوحِي حَتَّى أَرُدَّ عَلَيْهِ السَّلَامَ". (د)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലുമൊരാൾ എന്റെ മേൽ സലാം പറയുന്നുവെങ്കിൽ അല്ലാഹു എനിക്ക് എന്റെ ആത്മാവിനെ തിരിച്ചു നൽകുകയും അങ്ങനെ ഞാൻ അവന്റെ സലാം മടക്കുകയും ചയ്യാതിരിക്കില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَجْعَلُوا بُيُوتَكُمْ قُبُورًا، وَلَا تَجْعَلُوا قَبْرِي عِيدًا، وَصَلُّوا عَلَيَّ، فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُ كُنْتُمْ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ വീടുകളെ നിങ്ങൾ ഖബറിടങ്ങളാക്കരുത്. എന്റെ ഖബറിനെ നിങ്ങൾ ആഘോഷസ്ഥലമാക്കരുത്. നിങ്ങൾ എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലുക. നിങ്ങൾ എവിടെ യാണെങ്കിലും നിശ്ചയം നിങ്ങളുടെ സ്വലാത്ത് എനിക്ക് എത്തുന്നതാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 516, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرِيدُ قُبُورَ الشُّهَدَاءِ، حَتَّى إِذَا أَشْرَفْنَا عَلَى حَرَّةِ وَاقِمٍ، فَلَمَّا تَدَلَّيْنَا مِنْهَا وَإِذَا قُبُورٌ بِمَحْنِيَّةٍ، قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، أَقُبُورُ إِخْوَانِنَا هَذِهِ؟ قَالَ: "قُبُورُ أَصْحَابِنَا". فَلَمَّا جِئْنَا قُبُورَ الشُّهَدَاءِ قَالَ: "هَذِهِ قُبُورُ إِخْوَانِنَا". (د)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): രക്തസാക്ഷികളുടെ ഖബറിടങ്ങളെ സന്ദർശിക്കാൻ റസൂൽ(സ)യുടെ കൂടെ ഞങ്ങൾ പുറപ്പെട്ടു. അങ്ങനെ വാഖിം എന്ന ചരൽപ്രദേശത്തേക്ക് ഞങ്ങൾ പ്രവേശിച്ച് അവിടെനിന്ന് ഇറങ്ങിയപ്പോൾ ചെരിഞ്ഞ താഴ്വരയിൽ ചില ഖബറുകൾ കണ്ടു. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഇവ നമ്മുടെ സഹോദരങ്ങളുടെ ഖബറുകളാണോ? അവിടുന്ന് പറഞ്ഞു: "നമ്മുടെ കൂട്ടുകാരുടെ ഖബറുകളാണ്." അങ്ങനെ ഞങ്ങൾ രക്തസാക്ഷികളുടെ ഖബറുകളുടെ അടുത്തെത്തിയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇവ നമ്മുടെ സഹോദരങ്ങളുടെ ഖബറുകളാണ്." (ദ)', 'طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَاخَ بِالْبَطْحَاءِ الَّتِي بِذِي الْحُلَيْفَةِ فَصَلَّى بِهَا، فَكَانَ عَبْدُ اللَّهِ بْنُ عُمَرَ يَفْعَلُ ذَلِكَ. (ق,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) ദുൽഹുലൈഫയിലെ താഴ്വരയിൽ തന്റെ ഒട്ടകത്തെ മുട്ടുകുത്തിക്കുകയും അവിടെവെച്ച് നമസ്കരിക്കുകയും ചെയ്തു. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വും അപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'قَالَ مَالِكٌ: لَا يَنْبَغِي لِأَحَدٍ أَنْ يُجَاوِزَ الْمُعَرَّسَ إِذَا قَفَلَ رَاجِعًا إِلَى الْمَدِينَةِ، حَتَّى يُصَلِّيَ فِيهَا مَا بَدَا لَهُ، لِأَنَّهُ بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَّسَ بِهِ. (د)', 'മാലിക്(റ): മദീനയിലേക്കുള്ള മടക്കത്തിൽ മുഅർറസ് (റസൂൽ(സ) വിശ്രമിച്ച സ്ഥലം) പ്രദേശത്തുകൂടെ സഞ്ചരിക്കുമ്പോൾ അവിടെവെച്ച് തനിക്ക് തോന്നുന്നയത്ര നമസ്കരിക്കൽ ഏതൊരുത്തനും അത്യാവശ്യമാണ്. കാരണം നിശ്ചയം റസൂൽ(സ) വിശ്രമിക്കാൻവേണ്ടി അവിടെ ഇറങ്ങിയിരുന്നുവെന്ന് എനിക്ക് വിവരം ലഭിച്ചിട്ടുണ്ട്. (ദ)', null, 'മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى إِذَا كُنَّا بِحَرَّةِ السُّقْيَا الَّتِي كَانَتْ لِسَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ائْتُونِي بِوَضُوءٍ". فَتَوَضَّأَ ثُمَّ قَامَ فَاسْتَقْبَلَ الْقِبْلَةَ، ثُمَّ قَالَ: "اللَّهُمَّ إِنَّ إِبْرَاهِيمَ كَانَ عَبْدَكَ وَخَلِيلَكَ، وَدَعَا لِأَهْلِ مَكَّةَ بِالْبَرَكَةِ. وَأَنَا عَبْدُكَ وَرَسُولُكَ، أَدْعُوكَ لِأَهْلِ الْمَدِينَةِ أَنْ تُبَارِكَ لَهُمْ فِي مُدِّهِمْ وَصَاعِهِمْ، مِثْلَيْ مَا بَارَكْتَ لِأَهْلِ مَكَّةَ مَعَ الْبَرَكَةِ بَرَكَتَيْنِ". (د,ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ പുറപ്പെട്ടു. അങ്ങനെ സഅ്ദുബ്നു അബീവഖാസ്(റ)വിന്റെ ഉടമസ്ഥതയിലുള്ള ''സുഖ്യാ'' എന്ന ചരൽപ്രദേശത്ത് തിരുമേനി(സ) എത്തിയപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "എനിക്ക് വുളൂ ചെയ്യാനുള്ള വെള്ളം നിങ്ങൾ കൊണ്ടുവരിക." അങ്ങനെ അവിടുന്ന് വുളൂ ചെയ്ത് എഴുന്നേറ്റ് ഖിബ്ലയുടെ നേരെ മുന്നിട്ടുകൊണ്ട് പറഞ്ഞു: "അല്ലാഹുവേ, നിശ്ചയം ഇബ്റാഹീം(അ) നിന്റെ അടിമയും ''ഖലീലും'' (കൂട്ടുകാരൻ) ആയിരുന്നു. അദ്ദേഹം മക്കക്കാർക്ക് അനുഗ്രഹത്തിനുവേണ്ടി നിന്നോട് പ്രാർത്ഥിച്ചു. ഞാൻ നിന്റെ അടിമയും ദൂതനുമാണ്. മക്കക്കാർക്ക് നീ അനുഗ്രഹം ചെയ്തതുപോലെ, ആ അനുഗ്രഹത്തിന്റെ ഇരട്ടിയായി, മദീനക്കാർക്ക് അവരുടെ ''മുദ്ദിലും'' ''സ്വാഇലും'' (അളവുകൾ) നീ അനുഗ്രഹം ചെയ്യണമെന്ന് ഞാൻ നിന്നോട് പ്രാർത്ഥിക്കുന്നു." (ദ,തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 517, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَطَاعَ أَنْ يَمُوتَ بِالْمَدِينَةِ فَلْيَمُتْ بِهَا، فَإِنِّي أَشْفَعُ لِمَنْ يَمُوتُ بِهَا". (ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും മദീനയിൽവെച്ച് മരിക്കാൻ സാധിക്കുന്നുവെങ്കിൽ അവിടെവെച്ച് മരിച്ചുകൊള്ളട്ടെ. നിശ്ചയം അവിടെവെച്ച് മരണപ്പെടുന്നവർക്കുവേണ്ടി ഞാൻ ശിപാർശ ചെയ്യുന്നതാണ്." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مَوْلَاةً لَهُ أَتَتْهُ فَقَالَتْ: اشْتَدَّ عَلَيَّ الزَّمَانُ، وَإِنِّي أُرِيدُ أَنْ أَخْرُجَ إِلَى الْعِرَاقِ؟ قَالَ: فَهَلَّا إِلَى الشَّامِ أَرْضِ الْمَنْشَرِ؟ اصْبِرِي لَكَاعِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ صَبَرَ عَلَى شِدَّتِهَا وَلَأْوَائِهَا كُنْتُ لَهُ شَهِيدًا – أَوْ: شَفِيعًا – يَوْمَ الْقِيَامَةِ". (م,ت)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം അദ്ദേഹത്തിന്റെ ഒരു സേവക വന്നുകൊണ്ട് അദ്ദേഹത്തോട് പറഞ്ഞു: എന്റെ ജീവിതപ്രാരാബ്ധങ്ങൾ അധികരിച്ചിരിക്കുന്നു, നിശ്ചയം ഇറാഖിലേക്ക് പോകണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. അദ്ദേഹം ചോദിച്ചു: എങ്കിൽ പച്ചപ്പുകളുടെ നാടായ ശാമിലേക്ക് പോയിക്കൂടേ? വിവരം കുറഞ്ഞവളേ, നീ ക്ഷമിക്കുക. നിശ്ചയം റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും അതിലെ (മദീനയിലെ) പ്രയാസങ്ങളുടെയും ജീവിതപ്രാരാബ്ധങ്ങളുടെയും മേൽ ക്ഷമിച്ചാൽ അന്ത്യനാളിൽ ഞാൻ അവന് സാക്ഷിനിൽക്കുന്നതാണ്, അല്ലെങ്കിൽ: ശിപാർശ ചെയ്യുന്നതാണ്." (മു,ത)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','ത']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "آخِرُ قَرْيَةٍ مِنْ قُرَى الْإِسْلَامِ خَرَابًا الْمَدِينَةُ". حسن. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇസ്ലാമിക പ്രദേശങ്ങളിൽവെച്ച് ഏറ്റവും അവസാനം നശിക്കുന്ന പ്രദേശം മദീനയായിരിക്കും." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَعْرَابِيًّا بَايَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْإِسْلَامِ، فَأَصَابَهُ وَعَكٌ بِالْمَدِينَةِ، فَجَاءَ الْأَعْرَابِيُّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَقِلْنِي بَيْعَتِي. فَأَبَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ الْأَعْرَابِيُّ ثُمَّ جَاءَهُ فَقَالَ: أَقِلْنِي بَيْعَتِي. فَأَبَى، فَخَرَجَ الْأَعْرَابِيُّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْمَدِينَةُ كَالْكِيرِ: تَنْفِي خَبَثَهَا، وَتُنصِّعُ طَيِّبَهَا". (ق,د,ت)', 'ജാബിർ(റ): നിശ്ചയം ഒരു അഅ്റാബി റസൂൽ(സ)യോട് ഇസ്ലാമിന്റെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്തു. അങ്ങനെ മദീനയിൽവെച്ച് അദ്ദേഹത്തിന് ശക്തമായ പനി പിടിപെട്ടു. അപ്പോൾ അഅ്റാബി റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: എന്റെ ഉടമ്പടിയെ ഒഴിവാക്കിത്തന്നാലും (ഹിജ്റയെ ഒഴിവാക്കി നാട്ടിൽപോകാൻ അനുവദിച്ചാലും). എന്നാൽ റസൂൽ(സ) അതിന് വിസമ്മതിച്ചു. അപ്പോൾ അഅ്റാബി മടങ്ങുകയും ശേഷം റസൂൽ(സ)യുടെ അടുത്തുവന്ന് ഇപ്രകാരം പറയുകയും ചെയ്തു: എന്റെ ഉടമ്പടിയെ ഒഴിവാക്കിത്തന്നാലും. അപ്പോഴും റസൂൽ(സ) വിസമ്മതിച്ചു. അങ്ങനെ അഅ്റാബി തിരിച്ചുപോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം മദീന ഉല പോലെയാണ്: അതിലുള്ള മ്ലേഛതയെ അത് പുറംതള്ളുകയും നല്ലതിനെ വേർതിരിക്കുകയും ചെയ്യും." (ബു,മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَقُولُ: لَوْ رَأَيْتُ الظِّبَاءَ تَرْتَعُ بِالْمَدِينَةِ مَا ذَعَرْتُهَا، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا بَيْنَ لَابَتَيْهَا حَرَامٌ". (م,ت)', 'അബൂഹുറൈറ(റ): നിശ്ചയം അദ്ദേഹം ഇപ്രകാരം പറയുമായിരുന്നു: മദീനയിൽവെച്ച് മേഞ്ഞുനടക്കുന്ന മാനുകളെ ഞാൻ കാണുകയാണെങ്കിൽ അവയെ പേടിപ്പിക്കുകയില്ല (വേട്ടയാടുകയില്ല). നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അതിലെ (മദീനയിലെ) രണ്ട് ചരൽപ്രദേശങ്ങൾക്കിടയിലുള്ള സ്ഥലം പവിത്രമാണ്." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 518, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَلَعَ لَهُ أُحُدٌ، فَقَالَ: "هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ، اللَّهُمَّ إِنَّ إِبْرَاهِيمَ حَرَّمَ مَكَّةَ، وَإِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيْهَا". (م,ت)', 'അനസുബ്നു മാലിക്(റ): ഉഹ്ദ് പർവ്വതം റസൂൽ(സ)യുടെ ദൃഷ്ടിയിൽ പെട്ടപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇത് നമ്മെ സ്നേഹിക്കുകയും നാം അതിനെ സ്നേഹിക്കുകയും ചെയ്യുന്ന പർവ്വതമാണ്. അല്ലാഹുവേ, നിശ്ചയം ഇബ്റാഹീം(അ) മക്കയെ പവിത്രമായി പ്രഖ്യാപിച്ചു. ഇതിന്റെ (മദീനയുടെ) രണ്ടു ചരൽപ്രദേശങ്ങൾക്കിടയിലുള്ള സ്ഥലത്തെ നിശ്ചയം ഞാൻ പവിത്രമായി പ്രഖ്യാപിക്കുന്നു." (മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ أَوْحَى إِلَيَّ: أَيَّ هَؤُلَاءِ الثَّلَاثَةِ نَزَلْتَ فَهِيَ دَارُ هِجْرَتِكَ: الْمَدِينَةِ، أَوِ الْبَحْرَيْنِ، أَوْ قِنَّسْرِينَ". (ت)', 'ജരീറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു എനിക്ക് ഇപ്രകാരം വഹ്യ് അവതരിപ്പിച്ചു: മദീന, ബഹ്റൈൻ, ഖിന്നസ്രീൻ എന്നീ നാടുകളിൽ എവിടെയാണോ അവിടുന്ന് യാത്രയിറങ്ങുന്നത് അത് അവിടുത്തെ പലായനസ്ഥലമാണ്." (തു)', 'جَرِيرِ بْنِ عَبْدِ اللَّهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُمَّ إِنَّ إِبْرَاهِيمَ خَلِيلُكَ وَنَبِيُّكَ، وَإِنَّكَ حَرَّمْتَ مَكَّةَ عَلَى لِسَانِ إِبْرَاهِيمَ. اللَّهُمَّ وَأَنَا عَبْدُكَ وَنَبِيُّكَ، وَإِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيْهَا". (جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നിശ്ചയം ഇബ്റാഹീം(അ) നിന്റെ ഖലീലും പ്രവാചകനുമാണ്. നിശ്ചയം ഇബ്റാഹീം(അ)മിന്റെ നാവിലൂടെ നീ മക്കയെ പവിത്രമാക്കി. അല്ലാഹുവേ, ഞാൻ നിന്റെ അടിമയും പ്രവാചകനുമാണ്. നിശ്ചയം അതിലെ (മദീനയിലെ) രണ്ടു ചരൽപ്രദേശങ്ങൾക്കിടയിലുള്ള സ്ഥലത്തെ ഞാൻ പവിത്രമായി പ്രഖ്യാപിക്കുന്നു." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَنَسِ بْنِ مَالِك رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أُحُدًا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ، وَهُوَ عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ، وَعَيْرٌ عَلَى تُرْعَةٍ مِنْ تُرَعِ النَّارِ". [ز: فيه مدلس عنعنه]. (جه)', 'അനസുബ്നു മാലിക്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഉഹ്ദ് പർവ്വതം നമ്മെ സ്നേഹിക്കുകയും നാം അതിനെ സ്നേഹിക്കുകയും ചെയ്യുന്ന ഒരു പർവ്വതമാണ്. അത് സ്വർഗ്ഗീയ കവാടങ്ങളിലെ ഒരു കവാടത്തിനു സമീപത്താണ് നിലകൊള്ളുന്നത്. ''ഐർ'' പർവ്വതം നരക കവാടങ്ങളിലെ ഒരു കവാടത്തിനരികിലാണ് നിലകൊള്ളുന്നത്." ഇതിൽ ''അൻഅനത്'' രൂപത്തിൽ ഹദീസ് പറഞ്ഞ മുദല്ലസായ നിവേദകനുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه مدلس عنعنه', null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ إِبْرَاهِيمَ حَرَّمَ مَكَّةَ وَدَعَا لِأَهْلِهَا، وَإِنِّي حَرَّمْتُ الْمَدِينَةَ كَمَا حَرَّمَ إِبْرَاهِيمُ مَكَّةَ، وَإِنِّي دَعَوْتُ فِي صَاعِهَا وَمُدِّهَا، بِمِثْلَيْ مَا دَعَا بِهِ إِبْرَاهِيمُ لِأَهْلِ مَكَّةَ". (م)', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസിം(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും ഇബ്റാഹീം(അ) മക്കയെ പവിത്രമായി പ്രഖ്യാപിക്കുകയും അവിടത്തെയാളുകൾക്കുവേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്തു. ഇബ്റാഹീം(അ) മക്കയെ പവിത്രമായി പ്രഖ്യാപിച്ചതുപോലെ നിശ്ചയം ഞാൻ മദീനയെ പവിത്രമായി പ്രഖ്യാപിച്ചിരിക്കുന്നു. ഇബ്റാഹീം(അ) മക്കക്കാർക്കുവേണ്ടി പ്രാർത്ഥിച്ചതിന്റെ ഇരട്ടിയായി മദീനയിലെ സ്വാഇലും മുദ്ദിലും (അനുഗ്രഹത്തിനായി) നിശ്ചയം ഞാൻ പ്രാർത്ഥിച്ചിരിക്കുന്നു." (മു)', 'عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസിം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيِ الْمَدِينَةِ: أَنْ يُقْطَعَ عِضَاهُهَا، أَوْ يُقْتَلَ صَيْدُهَا". وَقَالَ: "الْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ، لَا يَدَعُهَا أَحَدٌ رَغْبَةً عَنْهَا إِلَّا أَبْدَلَ اللَّهُ فِيهَا مَنْ هُوَ خَيْرٌ مِنْهُ، وَلَا يَثْبُتُ أَحَدٌ عَلَى لَأْوَائِهَا وَجَهْدِهَا، إِلَّا كُنْتُ لَهُ شَفِيعًا – أَوْ: شَهِيدًا – يَوْمَ الْقِيَامَةِ". (م)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മദീനയിലെ മരങ്ങൾ മുറിക്കപ്പെടുകയോ വേട്ടമൃഗങ്ങൾ കൊല്ലപ്പെടുകയോ ചെയ്യാത്ത വിധം അതിലെ രണ്ടു ചരൽപ്രദേശങ്ങൾക്കിടയിലുള്ള സ്ഥലത്തെ ഞാൻ പവിത്രമായി പ്രഖ്യാപിക്കുന്നു." അവിടുന്ന് പറഞ്ഞു: "അവർ മനസ്സിലാക്കുന്ന പക്ഷം മദീന അവർക്ക് ഏറ്റവും പുണ്യമായ സ്ഥലമാണ്. അതിനോടുള്ള വെറുപ്പ് കാരണം അതിനെ ഉപേക്ഷിക്കുന്ന ഏതൊരാൾക്കും പകരമായി അവനേക്കാൾ ഉത്തമനായവനെ അവിടെ അല്ലാഹു പകരം വെക്കും. അവിടത്തെ പ്രയാസങ്ങളിലും പ്രാരാബ്ധങ്ങളിലും ക്ഷമിച്ചുകഴിയുന്ന വ്യക്തിക്കുവേണ്ടി അന്ത്യനാളിൽ ഞാൻ ശിപാർശ ചെയ്യാതിരിക്കില്ല, അല്ലെങ്കിൽ: സാക്ഷി നിൽക്കാതിരിക്കില്ല." (മു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 519, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَامِرِ بْنِ سَعْدٍ: أَنَّ سَعْدًا رَضِيَ اللهُ عَنْهُ رَكِبَ إِلَى قَصْرِهِ بِالْعَقِيقِ، فَوَجَدَ عَبْدًا يَقْطَعُ شَجَرًا – أَوْ يَخْبِطُهُ – فَسَلَبَهُ، فَلَمَّا رَجَعَ سَعْدٌ جَاءَهُ أَهْلُ الْعَبْدِ، فَكَلَّمُوهُ أَنْ يَرُدَّ عَلَى غُلَامِهِمْ – أَوْ: عَلَيْهِمْ – مَا أَخَذَ مِنْ غُلَامِهِمْ، فَقَالَ: مَعَاذَ اللَّهِ أَنْ أَرُدَّ شَيْئًا نَفَّلَنِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَأَبَى أَنْ يَرُدَّ عَلَيْهِمْ. (م)', 'ആമിറുബ്നു സഅ്ദ്(റ): നിശ്ചയം സഅ്ദ്(റ) അഖീഖിലുള്ള തന്റെ കോട്ടയിലേക്ക് വാഹനം കയറിയപ്പോൾ ഒരു അടിമ ഒരു മരം മുറിക്കുന്നത് - അല്ലെങ്കിൽ: മരത്തിൽനിന്ന് ഇലകൊഴിക്കുന്നത് - കണ്ടു. അദ്ദേഹം അടിമയിൽനിന്ന് (അവന്റെ പക്കലുണ്ടായിരുന്നത്) ബലംപ്രയോഗിച്ച് വാങ്ങി. ശേഷം സഅ്ദ്(റ) മടങ്ങിവന്നപ്പോൾ അടിമയുടെയാളുകൾ അദ്ദേഹത്തിന്റെ അടുത്ത് വന്ന് അടിമയിൽനിന്ന് കൈപറ്റിയ മുതലുകൾ തങ്ങളുടെ അടിമക്ക് - അല്ലെങ്കിൽ: തങ്ങൾക്ക് - തിരിച്ചു നൽകണമെന്ന് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) എനിക്ക് വിഹിതമായി നൽകിയ മുതൽ തിരിച്ചു നൽകുന്ന കാര്യത്തിൽ അല്ലാഹുവിനോട് ഞാൻ കാവൽ ചോദിക്കുന്നു. അങ്ങനെ അത് അവർക്ക് തിരിച്ചു നൽകാൻ അദ്ദേഹം വിസമ്മതിച്ചു. (മു)', 'عَامِرِ بْنِ سَعْدٍ', 'ആമിറുബ്നു സഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِك رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ اجْعَلْ بِالْمَدِينَةِ ضِعْفَيْ مَا بِمَكَّةَ مِنَ الْبَرَكَةِ". (ق)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, മക്കയിലുള്ളതിന്റെ ഇരട്ടി അനുഗ്രഹം മദീനയിൽ നീ നൽകണേ." (ബു,മു)', 'أَنَسِ بْنِ مَالِك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ يَزِيدَ بْنِ شَرِيكٍ التَّيْمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَطَبَنَا عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: مَنْ زَعَمَ أَنَّ عِنْدَنَا شَيْئًا نَقْرَؤُهُ إِلَّا كِتَابَ اللَّهِ وَهَذِهِ الصَّحِيفَةَ – صَحِيفَةٌ فِيهَا أَسْنَانُ الْإِبِلِ، وَأَشْيَاءُ مِنَ الْجِرَاحَاتِ – فَقَدْ كَذَبَ. قَالَ: وَفِيهَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَدِينَةُ حَرَامٌ مَا بَيْنَ عَيْرٍ إِلَى ثَوْرٍ، فَمَنْ أَحْدَثَ فِيهَا حَدَثًا أَوْ آوَى مُحْدِثًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ صَرْفًا وَلَا عَدْلًا. وَمَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ – أَوْ تَوَلَّى غَيْرَ مَوَالِيهِ – فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلَا عَدْلٌ. وَذِمَّةُ الْمُسْلِمِينَ وَاحِدَةٌ، يَسْعَى بِهَا أَدْنَاهُمْ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'യസീദുബ്നു ശരീകുത്തൈമീ(റ): ഞങ്ങളോട് പ്രഭാഷണം നടത്തിക്കൊണ്ടിരിക്കെ അലി(റ) പറഞ്ഞു: ഈ ഏടും - ഒട്ടകങ്ങളുടെ പ്രായത്തെക്കുറിച്ചും മുറിവ് പറ്റിയാലുള്ള ചില വിധികളെക്കുറിച്ചുമാണ് ആ ഏടിലുള്ളത് - അല്ലാഹുവിന്റെ ഗ്രന്ഥവുമല്ലാത്ത, നാം പാരായണം ചെയ്യുന്ന ഒന്ന് നമ്മുടെ പക്കലുണ്ടെന്ന് ആരെങ്കിലും പറഞ്ഞാൽ അവൻ കളവാണ് പറഞ്ഞത്. നിവേദകൻ പറയുന്നു: ആ ഏടിൽ ഇപ്രകാരമുണ്ടായിരുന്നു: റസൂൽ(സ) പറഞ്ഞു: "മദീന, ഐറ് മുതൽ സൗറ് വരെ പവിത്രമാണ്. അതിൽ ആരെങ്കിലും പുതുതായി ഉണ്ടാക്കിയാൽ, അല്ലെങ്കിൽ പുതുതായി ഉണ്ടാക്കുന്നവന് അഭയം നൽകിയാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അന്ത്യദിനത്തിൽ അവനിൽ നിന്ന് അല്ലാഹു നിർബന്ധമോ സുന്നത്തോ ആയ ഒരു കർമങ്ങളും സ്വീകരിക്കുന്നതല്ല. വല്ലവനും തന്റെ പിതാവല്ലാത്തവന്റെ മേൽ പിതൃത്വം ആരോപിച്ചാൽ - അല്ലെങ്കിൽ തനിക്ക് അടിമത്വത്തിൽ നിന്ന് മോചനം നൽകിയവനല്ലാത്ത ഒരാളെ അയാളാണ് തന്നെ മോചിപ്പിച്ചതെന്ന് പറഞ്ഞാൽ - അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവന്റെ സുന്നത്തും നിർബന്ധവുമായ ഒരു കർമ്മവും സ്വീകരിക്കപ്പെടുന്നതല്ല. മുസ്ലിംകളുടെ കരാർ ഏകമാണ്. അവരിലെ ഏറ്റവും താഴ്ന്നവരും അത് ഏറ്റെടുക്കും." (ബു,മു,ദ,തു,ന)', 'يَزِيدَ بْنِ شَرِيكٍ التَّيْمِيِّ', 'യസീദുബ്നു ശരീകുത്തൈമീ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 520, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا كَتَبْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا الْقُرْآنَ، وَمَا فِي هَذِهِ الصَّحِيفَةِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَدِينَةُ حَرَامٌ مَا بَيْنَ عَائِرٍ إِلَى ثَوْرٍ، فَمَنْ أَحْدَثَ حَدَثًا، أَوْ آوَى مُحْدِثًا، فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ عَدْلٌ وَلَا صَرْفٌ، وَذِمَّةُ الْمُسْلِمِينَ وَاحِدَةٌ يَسْعَى بِهَا أَدْنَاهُمْ، فَمَنْ أَخْفَرَ مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ عَدْلٌ وَلَا صَرْفٌ، وَمَنْ وَالَى قَوْمًا بِغَيْرِ إِذْنِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ عَدْلٌ وَلَا صَرْفٌ". (ق,د,ت)', 'അലി(റ): ഈ ഏടിലുള്ളതും ഖുർആനുമല്ലാതെ മറ്റൊന്നും റസൂൽ(സ)യിൽനിന്ന് നാം രേഖപ്പെടുത്തിവെച്ചിട്ടില്ല. അദ്ദേഹം പറയുന്നു: റസൂൽ(സ) പറഞ്ഞു: "മദീന, ആഇർ മുതൽ സൗറ് വരെ പവിത്രമാണ്. ആരെങ്കിലും പുതുതായി ഉണ്ടാക്കിയാൽ, അല്ലെങ്കിൽ പുതുതായി ഉണ്ടാക്കുന്നവന് അഭയം നൽകിയാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവനിൽ നിന്ന് നിർബന്ധമോ സുന്നത്തോ ആയ ഒരു കർമ്മവും സ്വീകരിക്കപ്പെടുന്നതല്ല. മുസ്ലിംകളുടെ കരാർ ഏകമാണ്. അവരിലെ ഏറ്റവും താഴ്ന്നവരും അത് ഏറ്റെടുക്കും. ആരെങ്കിലും ഒരു മുസ്ലിമുമായി കരാർലംഘനം നടത്തിയാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവനിൽ നിന്ന് നിർബന്ധമോ സുന്നത്തോ ആയ ഒരു കർമ്മവും സ്വീകരിക്കപ്പെടുന്നതല്ല. തനിക്ക് അടിമത്വത്തിൽ നിന്ന് മോചനം നൽകിയവരുടെ അനുവാദമില്ലാതെ, അവരല്ലാത്ത ഒരാളെ സംബന്ധിച്ച് അയാളാണ് തന്നെ മോചിപ്പിച്ചതെന്ന് വല്ലവനും പറഞ്ഞാൽ, അവന്റെമേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും മുഴുജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവന്റെ സുന്നത്തും നിർബന്ധവുമായ ഒരു കർമ്മവും സ്വീകരിക്കപ്പെടുന്നതല്ല." (ബു,മു,ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِأَوَّلِ الثَّمَرِ فَيَقُولُ: "اللَّهُمَّ بَارِكْ لَنَا فِي مَدِينَتِنَا وَفِي ثِمَارِنَا، وَفِي مُدِّنَا وَفِي صَاعِنَا، بَرَكَةً مَعَ بَرَكَةٍ". ثُمَّ يُعْطِيهِ أَصْغَرَ مَنْ يَحْضُرُهُ مِنَ الْوِلْدَانِ. (م)', 'അബൂഹുറൈറ(റ): ആദ്യമായുണ്ടാകുന്ന പഴം നിശ്ചയം റസൂൽ(സ)യുടെ അടുത്ത് കൊണ്ടുവരപ്പെടുമായിരുന്നു, അപ്പോൾ അവിടുന്ന് പറയും: "അല്ലാഹുവേ, ഞങ്ങളുടെ മദീനയിലും പഴങ്ങളിലും മുദ്ദിലും സ്വാഇലും (അളവുകൾ) നീ ഇരട്ടി അനുഗ്രഹം ചെയ്യണേ." ശേഷം അവിടുത്തെ സമീപത്ത് വരുന്ന ഏറ്റവും പ്രായംകുറഞ്ഞ കുട്ടിക്ക് അത് നൽകും. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَدِينَةُ حَرَمٌ مِنْ كَذَا إِلَى كَذَا، لَا يُقْطَعُ شَجَرُهَا وَلَا يُحْدَثُ فِيهَا حَدَثٌ، مَنْ أَحْدَثَ فِيهَا حَدَثًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ". (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഇന്ന സ്ഥലം മുതൽ ഇന്നതുവരെ മദീന പവിത്രമാക്കപ്പെട്ട നാടാണ്. അതിലെ മരങ്ങൾ മുറിക്കപ്പെടാനോ അതിൽ പുതുതായി വല്ലതും ഉണ്ടാക്കപ്പെടാനോ പാടില്ല. ആരെങ്കിലും അതിൽ പുതുതായി വല്ലതും ഉണ്ടാക്കിയാൽ അവനുമേൽ അല്ലാഹുവിന്റെയും മലക്കുകളുടെയും സർവ്വജനങ്ങളുടെയും ശാപമുണ്ടായിരിക്കുന്നതാണ്." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 521, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُرِّمَ مَا بَيْنَ لَابَتَيِ الْمَدِينَةِ عَلَى لِسَانِي". قَالَ: وَأَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَنِي حَارِثَةَ فَقَالَ: "أَرَاكُمْ يَا بَنِي حَارِثَةَ قَدْ خَرَجْتُمْ مِنَ الْحَرَمِ". ثُمَّ الْتَفَتَ فَقَالَ: "بَلْ أَنْتُمْ فِيهِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ നാവിലൂടെ മദീനയിലെ രണ്ട് ചരൽപ്രദേശങ്ങൾക്കിടയിലെ സ്ഥലം പവിത്രമാക്കപ്പെട്ടിരിക്കുന്നു." നിവേദകൻ പറയുന്നു: നബി(സ) ബനൂഹാരിസ ഗോത്രത്തിന്റെ അടുത്ത് വന്ന് പറഞ്ഞു: "ബനൂഹാരിസാ ഗോത്രമേ, നിങ്ങൾ താമസിക്കുന്നത് ഹറമിനു (പവിത്രമാക്കപ്പെട്ട സ്ഥലം) പുറത്താണെന്നാണ് എന്റെ അഭിപ്രായം." ശേഷം തിരിഞ്ഞുകൊണ്ട് അവിടുന്ന് പറഞ്ഞു: "അല്ല, നിങ്ങൾ അതിനുള്ളിൽ തന്നെയാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، فِي هَذِهِ الْقِصَّةِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُخْتَلَى خَلَاهَا، وَلَا يُنَفَّرُ صَيْدُهَا، وَلَا تُلْتَقَطُ لُقَطَتُهَا إِلَّا لِمَنْ أَشَادَ بِهَا، وَلَا يَصْلُحُ لِرَجُلٍ أَنْ يَحْمِلَ فِيهَا السِّلَاحَ لِقِتَالٍ، وَلَا يَصْلُحُ أَنْ يُقْطَعَ مِنْهَا شَجَرَةٌ، إِلَّا أَنْ يَعْلِفَ رَجُلٌ بَعِيرَهُ". (د)', 'ഈ സംഭവത്തിൽ (അലി(റ) തന്റെ ഏടിനെക്കുറിച്ച് പറഞ്ഞ സംഭവം) അലി(റ) നിവേദനം ചെയ്യുന്നു: നബി(സ) പറഞ്ഞു: "അതിലെ (മദീനയിലെ) മരങ്ങൾ മുറിക്കപ്പെടുകയോ വേട്ടമൃഗങ്ങൾ ഓടിക്കപ്പെടുകയോ വീണുകിട്ടിയ വസ്തുക്കൾ എടുക്കപ്പെടുകയോ ചെയ്യാൻ പാടില്ല, വീണുകിട്ടിയ വസ്തുവിനെ സംബന്ധിച്ച് പരസ്യം ചെയ്യുന്നവനൊഴികെ. ഒരാളും യുദ്ധത്തിനുവേണ്ടി അവിടെ ആയുധം ഏന്താൻ പാടില്ല. അതിലെ മരങ്ങൾ മുറിക്കപ്പെടാൻ പാടില്ല, ഒട്ടകത്തിന് തീറ്റ കൊടുക്കാൻ വേണ്ടിയല്ലാതെ." (ദ)', 'عَلِيٍّ', 'ഈ സംഭവത്തിൽ (അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَدِيِّ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَمَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّ نَاحِيَةٍ مِنَ الْمَدِينَةِ بَرِيدًا بَرِيدًا: لَا يُخْبَطُ شَجَرُهُ وَلَا يُعْضَدُ، إِلَّا مَا يُسَاقُ بِهِ الْجَمَلُ. (د)', 'അദിയ്യുബ്നു സൈദ്(റ): മദീനയുടെ എല്ലാ ഭാഗങ്ങളെയും ഓരോരോ ബരീദ് (പന്ത്രണ്ട് മൈൽ ദൂരമുള്ള അളവ്) കണക്കാക്കി റസൂൽ(സ) സംരക്ഷിത മേഖലയായി പ്രഖ്യാപിച്ചു. അവിടെയുള്ള മരങ്ങൾ മുറിക്കപ്പെടുകയോ അതിലെ ഇലകൾ കൊഴിക്കപ്പെടുകയോ ചെയ്യാൻ പാടില്ല, ഒട്ടകങ്ങൾക്ക് തീറ്റയായി നൽകുന്നതൊഴികെ. (ദ)', 'عَدِيِّ بْنِ زَيْدٍ', 'അദിയ്യുബ്നു സൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 522, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ: أَخَذَ رَجُلًا يَصِيدُ فِي حَرَمِ الْمَدِينَةِ الَّذِي حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَلَبَهُ ثِيَابَهُ، فَجَاءَ مَوَالِيهِ فَكَلَّمُوهُ فِيهِ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ هَذَا الْحَرَمَ وَقَالَ: "مَنْ أَخَذَ أَحَدًا يَصِيدُ فِيهِ فَلْيَسْلُبْهُ ثِيَابَهُ". فَلَا أَرُدُّ عَلَيْكُمْ طُعْمَةً أَطْعَمَنِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنْ إِنْ شِئْتُمْ دَفَعْتُ إِلَيْكُمْ ثَمَنَهُ. (د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പവിത്രമായതായി പ്രഖ്യാപിച്ച മദീനയിലെ ഹറമിൽവെച്ച് വേട്ടയാടുന്ന ഒരാളെ അദ്ദേഹം പിടികൂടുകയും അവന്റെ വസ്ത്രങ്ങൾ ബലംപ്രയോഗിച്ച് വാങ്ങുകയും ചെയ്തു. അപ്പോൾ അയാളുടെ ഉടമകൾ വന്ന് അക്കാര്യത്തിൽ അദ്ദേഹത്തോട് സംസാരിച്ചു. അന്നേരം സഅ്ദ്(റ) പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) ഈ ഹറമിനെ പവിത്രമായതായി പ്രഖ്യാപിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "അവിടെവെച്ച് വേട്ടയാടുന്ന ഒരാളെ ആരെങ്കിലും പിടികൂടിയാൽ അവന്റെ വസ്ത്രങ്ങളെ ബലംപ്രയോഗിച്ച് വാങ്ങിക്കൊള്ളട്ടെ." റസൂൽ(സ) എനിക്ക് നൽകിയ ഒരു മുതൽ ഞാൻ നിങ്ങൾക്ക് തിരിച്ചു നൽകുകയില്ല. നിങ്ങൾക്കുവേണമെങ്കിൽ അതിന്റെ വില ഞാൻ നൽകാം. (ദ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 522, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ وَجَدَ عَبِيدًا مِنْ عَبِيدِ الْمَدِينَةِ يَقْطَعُونَ مِنْ شَجَرِ الْمَدِينَةِ، فَأَخَذَ مَتَاعَهُمْ، وَقَالَ – يَعْنِي لِمَوَالِيهِمْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى أَنْ يُقْطَعَ مِنْ شَجَرِ الْمَدِينَةِ شَيْءٌ، وَقَالَ: "مَنْ قَطَعَ مِنْهُ شَيْئًا فَلِمَنْ أَخَذَهُ سَلَبُهُ". (م،د)', 'സഅ്ദ്(റ): മദീനയിലെ അടിമകളിൽ ചിലർ മദീനയിലെ മരം മുറിക്കുന്നത് അദ്ദേഹം കണ്ടു. അപ്പോൾ അദ്ദേഹം അവരുടെ ചരക്കുകൾ കൈവശപ്പെടുത്തിക്കൊണ്ട് അവരുടെ ഉടമസ്ഥരോട് പറഞ്ഞു: മദീനയിലെ മരങ്ങളിൽ വല്ലതും മുറിക്കപ്പെടുന്നതിനെ റസൂൽ(സ) നിരോധിക്കുന്നതായി ഞാൻ കേട്ടു. അവിടുന്ന് പറഞ്ഞു: "അതിൽനിന്ന് വല്ലതും ആരെങ്കിലും മുറിച്ചാൽ അവന്റെ ശരീരത്തിലുള്ള മുതലുകൾ അവനെ പിടികൂടുന്നവനുള്ളതാണ്." (മു,ദ)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُخْبَطُ وَلَا يُعْضَدُ حِمَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنْ يُهَشُّ هَشًّا رَفِيقًا". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "റസൂൽ(സ)യുടെ സംരക്ഷിതമേഘലയിലെ മരങ്ങൾ മുറിക്കപ്പെടുകയോ ഇലകൊഴിക്കപ്പെടുകയോ ചെയ്യാൻ പാടില്ല. എന്നാൽ ഏറ്റവും മയത്തോടുകൂടെ അതിൽനിന്ന് (ഇലകൾ) വീഴ്ത്താം." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَدِمَ مِنْ سَفَرٍ، فَأَبْصَرَ دَرَجَاتِ الْمَدِينَةِ أَوْضَعَ نَاقَتَهُ، وَإِنْ كَانَتْ دَابَّةً حَرَّكَهَا. وَزَادَ فِي رِوَايَةٍ: مِنْ حُبِّهَا. (خ)', 'അനസ്(റ): റസൂൽ(സ) യാത്ര കഴിഞ്ഞുവന്ന് മദീനയിലേക്കുള്ള വഴികൾ കണ്ടാൽ തന്റെ ഒട്ടകത്തെ വേഗത്തിൽ ഓടിക്കുമായിരുന്നു. മറ്റു വല്ല മൃഗവുമാണെങ്കിൽ അതിനെ (വേഗത്തിൽ) ചലിപ്പിക്കും. മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: മദീനയോടുള്ള സ്നേഹം കാരണത്താൽ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=10 and h.hadith_no=36), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: മദീനയോടുള്ള സ്നേഹം കാരണത്താൽ. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ وُعِكَ أَبُو بَكْرٍ وَبِلَالٌ رَضِيَ اللهُ عَنْهُمَا، فَكَانَ أَبُو بَكْرٍ إِذَا أَخَذَتْهُ الْحُمَّى يَقُولُ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ، وَمِنْبَرِي عَلَى حَوْضِي". (م،ت)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "എന്റെ വീടിനും മിമ്പറിനും ഇടയിലുള്ള സ്ഥലം സ്വർഗ്ഗത്തോപ്പുകളിലെ ഒരു തോപ്പാണ്. എന്റെ മിമ്പർ എന്റെ ഹൗളിനു (ഹൗളുൽ കൗസർ) സമീപത്താണ്." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ". وَقَالَ: "صَلَاةٌ فِي مَسْجِدِي هَذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنَ الْمَسَاجِدِ، إِلَّا الْمَسْجِدَ الْحَرَامَ". (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ വീടിനും മിമ്പറിനും (പ്രസംഗപീഠം) ഇടയിലുള്ള സ്ഥലം സ്വർഗ്ഗത്തോപ്പുകളിൽപെട്ട ഒരു തോപ്പാണ്." അവിടുന്ന് പറഞ്ഞു: "എന്റെ ഈ പള്ളിയിൽവെച്ചുള്ള ഒരു നമസ്കാരം മസ്ജിദുൽഹറാം ഒഴികെയുള്ള മറ്റു പള്ളികളിൽവെച്ചുള്ള ആയിരം നമസ്കാരങ്ങളേക്കാൾ പുണ്യമുള്ളതാണ്." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللهَ تَعَالَى سَمَّى الْمَدِينَةَ طَابَةَ". (م)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം അല്ലാഹു മദീനയെ ''ത്വാബ'' എന്ന് നാമകരണം ചെയ്തിരിക്കുന്നു." (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي حُمَيْدٍ [السَّاعِدِي] رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ تَبُوكَ حَتَّى أَشْرَفْنَا عَلَى الْمَدِينَةِ، فَقَالَ: "هَذِهِ طَابَةُ". (خ)', 'അബീഹുമൈദുസ്സാഇൗദീ(റ): നബി(സ)യോടൊന്നിച്ച് ഞങ്ങൾ തബൂഖിൽനിന്ന് മടങ്ങിവരികയും അങ്ങനെ മദീനയോട് അടുക്കുകയും ചെയ്തപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഇത് ത്വാബ (മദീനയുടെ മറ്റൊരു നാമം) യാണ്." (ബു)', 'أَبِي حُمَيْدٍ [السَّاعِدِي]', 'അബീഹുമൈദുസ്സാഇൗദീ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'السَّاعِدِي', null, 524, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْإِيمَانَ لَيَأْرِزُ إِلَى الْمَدِينَةِ كَمَا تَأْرِزُ الْحَيَّةُ إِلَى جُحْرِهَا". (ق،جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "പാമ്പ് അതിന്റെ മാളത്തിലേക്ക് അണയുന്നതുപോലെ നിശ്ചയം ഈമാൻ മദീനയിലേക്ക് അണയും (മടങ്ങും)." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي سَعِيدٍ مَوْلَى الْمَهْرِيِّ: أَنَّهُ جَاءَ أَبَا سَعِيدٍ الْخُدْرِيَّ رَضِيَ اللهُ عَنْهُ لَيَالِيَ الْحَرَّةِ، فَاسْتَشَارَهُ فِي الْجَلَاءِ مِنَ الْمَدِينَةِ، وَشَكَا إِلَيْهِ أَسْعَارَهَا وَكَثْرَةَ عِيَالِهِ، وَأَخْبَرَهُ أَنْ لَا صَبْرَ لَهُ عَلَى جَهْدِ الْمَدِينَةِ وَلَأْوَائِهَا، فَقَالَ [لَهُ: وَيْحَكَ، لَا آمُرُكَ بِذَلِكَ] إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَصْبِرُ أَحَدٌ عَلَى لَأْوَائِهَا فَيَمُوتَ، إِلَّا كُنْتُ لَهُ شَفِيعًا – أَوْ: شَهِيدًا – يَوْمَ الْقِيَامَةِ إِذَا كَانَ مُسْلِمًا". (م)', 'അബൂസഈദ് മൗലൽ മഹ്രി(റ): ഹർറാ സംഭവത്തിന്റെ രാവുകളിൽ അദ്ദേഹം അബൂസഈദുൽ ഖുദ്രി(റ)വിന്റെ അടുത്ത് വരികയും മദീനയിൽനിന്ന് നാടുവിടുന്ന വിഷയത്തെ സംബന്ധിച്ച് അദ്ദേഹത്തിന്റെ അഭിപ്രായമാരായുകയും ചെയ്തു. മദീനയിലെ വില വർദ്ധനവിനെയും തന്റെ ആശ്രിതർ അധികരിച്ചതിനെയും അദ്ദേഹം പരാതിപ്പെട്ടു. മദീനയിലെ പ്രയാസങ്ങളും ബുദ്ധിമുട്ടുകളും തനിക്ക് സഹിക്കാൻ കഴിയുന്നില്ലെന്നും അദ്ദേഹം പറഞ്ഞു. അപ്പോൾ അബൂസഈദ്(റ) പറഞ്ഞു: നിനക്കു നാശം, അത് (നാടുവിടാൻ) ഞാൻ നിന്നോട് കൽപിക്കുകയില്ല. നിശ്ചയം റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അതിലെ (മദീനയിലെ) പ്രയാസങ്ങളുടെ പേരിൽ ക്ഷമ കൈക്കൊണ്ട് മരണം വരിക്കുന്ന ഏതൊരു വ്യക്തിക്കും, അവൻ മുസ്ലിമാണെങ്കിൽ, അന്ത്യനാളിൽ ഞാൻ ശിപാർശ ചെയ്യുന്നതാണ് - അല്ലെങ്കിൽ: അവനുവേണ്ടി സാക്ഷി നിൽക്കുന്നതാണ്." (മു)', 'أَبِي سَعِيدٍ مَوْلَى الْمَهْرِيِّ', 'അബൂസഈദ് മൗലൽ മഹ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَهُ: وَيْحَكَ، لَا آمُرُكَ بِذَلِكَ', null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَدِمْنَا الْمَدِينَةَ وَهِيَ وَبِيئَةٌ، فَاشْتَكَى أَبُو بَكْرٍ وَاشْتَكَى بِلَالٌ، فَلَمَّا رَأَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَكْوَى أَصْحَابِهِ قَالَ: "اللَّهُمَّ حَبِّبْ إِلَيْنَا الْمَدِينَةَ كَمَا حَبَّبْتَ مَكَّةَ أَوْ أَشَدَّ، وَصَحِّحْهَا، وَبَارِكْ لَنَا فِي صَاعِهَا وَمُدِّهَا، وَحَوِّلْ حُمَّاهَا إِلَى الْجُحْفَةِ". (م)', 'ആഇശ(റ): മദീനയിൽ രോഗങ്ങൾ അതികരിച്ച സമയത്താണ് ഞങ്ങൾ അവിടെയെത്തിയത്. അങ്ങനെ അബൂബക്ർ(റ)വിനും ബിലാൽ(റ)വിനും രോഗം ബാധിച്ചു. തന്റെ അനുചരരുടെ രോഗാവസ്ഥ കണ്ടപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, മക്കയോടുള്ള സ്നേഹംപോലെ, എന്നല്ല അതിനേക്കാൾ ശക്തമായ സ്നേഹം മദീനയോടും ഞങ്ങൾക്ക് നീ നൽകണേ. അതിനെ നീ ആരോഗ്യപൂർണ്ണമാക്കണേ, അതിലെ മുദ്ദിലും സ്വാഇലും നീ ഞങ്ങൾക്ക് അനുഗ്രഹം ചെയ്യണേ. അവിടത്തെ പനിയെ ''ജുഹ്ഫ''യുടെ ഭാഗത്തേക്ക് നീക്കിക്കളയണേ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 525, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ سُفْيَانَ بْنِ أَبِي زُهَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تُفْتَحُ الْيَمَنُ، فَيَأْتِي قَوْمٌ يُبِسُّونَ فَيَتَحَمَّلُونَ بِأَهْلِهِمْ وَمَنْ أَطَاعَهُمْ، وَالْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ. وَتُفْتَحُ الشَّامُ. فَيَأْتِي قَوْمٌ يُبِسُّونَ فَيَتَحَمَّلُونَ بِأَهْلِيهِمْ وَمَنْ أَطَاعَهُمْ، وَالْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ. وَتُفْتَحُ الْعِرَاقُ، فَيَأْتِي قَوْمٌ يُبِسُّونَ فَيَتَحَمَّلُونَ بِأَهْلِيهِمْ وَمَنْ أَطَاعَهُمْ، وَالْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ". (ق)', 'സുഫ്യാനുബ്നു അബീസുഹൈർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "യമൻ ജയിച്ചടക്കപ്പെടും. അപ്പോൾ ഒരു കൂട്ടം ആളുകൾ വാഹനങ്ങളെ വേഗത്തിലോടിച്ചുകൊണ്ട് വരും. സ്വന്തം കുടുംബത്തെയും തങ്ങളെ അനുസരിക്കുന്നവരെയും കൂട്ടി അവർ (മദീനയിൽനിന്ന്) യാത്ര പോകും. അവർ മനസ്സിലാക്കുന്നപക്ഷം മദീന തന്നെയായിരിക്കും അവർക്ക് ഉത്തമം. സിരിയ ജയിച്ചടക്കപ്പെടും. അപ്പോൾ ഒരു കൂട്ടം ആളുകൾ വാഹനങ്ങളെ വേഗത്തിലോടിച്ചുകൊണ്ട് വരും. സ്വന്തം കുടുംബത്തെയും തങ്ങളെ അനുസരിക്കുന്നവരെയും കൂട്ടി അവർ (മദീനയിൽനിന്ന്) യാത്ര പോകും. അവർ മനസ്സിലാക്കുന്നപക്ഷം മദീന തന്നെയായിരിക്കും അവർക്ക് ഉത്തമം. ഇറാഖ് ജയിച്ചടക്കപ്പെടും. അപ്പോൾ ഒരു കൂട്ടം ആളുകൾ വാഹനങ്ങളെ വേഗത്തിലോടിച്ചുകൊണ്ട് വരും. സ്വന്തം കുടുംബത്തെയും തങ്ങളെ അനുസരിക്കുന്നവരെയും കൂട്ടി അവർ (മദീനയിൽനിന്ന്) യാത്ര പോകും. അവർ മനസ്സിലാക്കുന്നപക്ഷം മദീന തന്നെയായിരിക്കും അവർക്ക് ഉത്തമം." (ബു,മു)', 'سُفْيَانَ بْنِ أَبِي زُهَيْرٍ', 'സുഫ്യാനുബ്നു അബീസുഹൈർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَتْرُكُونَ الْمَدِينَةَ عَلَى خَيْرِ مَا كَانَتْ، لَا يَغْشَاهَا إِلَّا الْعَوَافِ – يُرِيدُ عَوَافِيَ السِّبَاعِ وَالطَّيْرِ – وَآخِرُ مَنْ يُحْشَرُ رَاعِيَانِ مِنْ مُزَيْنَةَ، يُرِيدَانِ الْمَدِينَةَ يَنْعِقَانِ بِغَنَمِهِمَا، فَيَجِدَانِهَا وَحْشًا، حَتَّى إِذَا بَلَغَا ثَنِيَّةَ الْوَدَاعِ خَرَّا عَلَى وُجُوهِهِمَا". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മദീന ക്ഷേമത്തിലാകുന്ന ഘട്ടത്തിൽ ജനങ്ങൾ മദീന വിട്ടുപോകും. അന്ന് ഇരതേടുന്ന ജന്തുക്കൾ മാത്രമാണ് മദീനയിൽ താമസിക്കുക - ഇരതേടുന്ന പക്ഷികളെയും വേട്ടമൃഗങ്ങളെയുമാണ് തിരുമേനി(സ) ഉദ്ദേശിക്കുന്നത് -. തങ്ങളുടെ ആടുകളെ തെളിച്ചുകൊണ്ട് മദീനയിലേക്ക് വരുന്ന മുസൈനാ ഗോത്രത്തിലെ രണ്ടു ആട്ടിടയന്മാരായിരിക്കും അവസാനമായി അവിടെയെത്തുക. മദീന ജനവാസമില്ലാതെ കിടക്കുന്നത് അവർ കാണും. അങ്ങനെ ''സനിയ്യത്തുൽ വിദാഇൽ'' എത്തുമ്പോൾ അവർ രണ്ടുപേരും മുഖം കുത്തിവീഴും." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ أَعْرَابِيٌّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَبَايَعَهُ عَلَى الْإِسْلَامِ، فَجَاءَ مِنَ الْغَدِ مَحْمُومًا، فَقَالَ: أَقِلْنِي، فَأَبَى، ثَلَاثَ مِرَارٍ، فَقَالَ: "الْمَدِينَةُ كَالْكِيرِ: تَنْفِي خَبَثَهَا وَيَنْصَعُ طَيِّبُهَا". (خ)', 'ജാബിർ(റ): ഒരു അഅ്റാബി നബി(സ)യുടെ അടുത്ത് വന്ന് ഇസ്ലാമിന്റെ കാര്യത്തിൽ അവിടുത്തോട് ഉടമ്പടി ചെയ്തു. അങ്ങനെ പനി പിടിച്ചുകൊണ്ട് പിറ്റേ ദിവസം അദ്ദേഹം വന്നുകൊണ്ട് പറഞ്ഞു: എന്റെ ഉടമ്പടിയെ ഒഴിവാക്കിത്തന്നാലും (ഹിജ്റയെ ഒഴിവാക്കി നാട്ടിൽപോകാൻ അനുവദിച്ചാലും). എന്നാൽ റസൂൽ(സ) അതിന് വിസമ്മതിച്ചു. മൂന്നു പ്രാവശ്യം അദ്ദേഹം അപ്രകാരം ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മദീന ഉല പോലെയാണ്: അതിലുള്ള മ്ലേഛതയെ അത് പുറംതള്ളുകയും നല്ലതിനെ വേർതിരിക്കുകയും ചെയ്യും." (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ بِقَرْيَةٍ تَأْكُلُ الْقُرَى، يَقُولُونَ يَثْرِبُ، وَهِيَ الْمَدِينَةُ، تَنْفِي النَّاسَ كَمَا يَنْفِي الْكِيرُ خَبَثَ الْحَدِيدِ". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "(എല്ലാ) നാടുകളെയും ഭക്ഷിക്കുന്ന (ജയിച്ചടക്കുന്ന) ഒരു നാട്ടിലേക്ക് പോകാൻ എനിക്ക് കൽപന ലഭിച്ചിരിക്കുന്നു. ആളുകൾ ''യസ്രിബ്'' എന്നാണ് അതിനെ വിളിക്കുന്നത്. മദീനയാണത്. ഉല ഇരുമ്പിലെ മ്ലേഛതയെ പുറത്തുകളയുംപോലെ മദീന ജനങ്ങളെ ശുദ്ധീകരിക്കും (ദുശിച്ചവരെ പുറത്താക്കും)." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 526, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَأْتِي عَلَى النَّاسِ زَمَانٌ، يَدْعُو الرَّجُلُ ابْنَ عَمِّهِ وَقَرِيبَهُ: هَلُمَّ إِلَى الرَّخَاءِ هَلُمَّ إِلَى الرَّخَاءِ، وَالْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ، وَالَّذِي نَفْسِي بِيَدِهِ، لَا يَخْرُجُ مِنْهُمْ أَحَدٌ – رَغْبَةً عَنْهَا – إِلَّا أَخْلَفَ اللهُ فِيهَا خَيْرًا مِنْهُ. أَلَا، إِنَّ الْمَدِينَةَ كَالْكِيرِ تُخْرِجُ الْخَبِيثَ، لَا تَقُومُ السَّاعَةُ حَتَّى تَنْفِيَ الْمَدِينَةُ شِرَارَهَا، كَمَا يَنْفِي الْكِيرُ خَبَثَ الْحَدِيدِ". (م)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾക്ക് ഒരു കാലം വരും. അന്ന് ഒരാൾ തന്റെ കുടുംബക്കാരനെയും പിതൃവ്യപുത്രനെയും വിളിച്ചുകൊണ്ട് പറയും: ക്ഷേമത്തിലേക്ക് വരിക, ക്ഷേമത്തിലേക്ക് വരിക (മദീനയിൽനിന്ന് പുറത്തു വരിക). അവർ മനസ്സിലാക്കുന്നപക്ഷം മദീനയാണ് അവർക്ക് ഉത്തമം. എന്റെ ആത്മാവിനെ നിയന്ത്രിക്കുന്നവൻ തന്നെ സത്യം, മദീനയോടുള്ള വെറുപ്പ് കാരണത്താൽ അവിടെനിന്ന് പുറത്തു പോകുന്ന ഏതൊരുത്തന്നും പകരമായി അവനേക്കാൾ ഉത്തമനായവനെ അവിടെ അല്ലാഹു കൊണ്ടുവരുന്നതാണ്. അറിയുക, നിശ്ചയം മദീന മ്ലേഛമായതിനെ പുറംതള്ളുന്ന ഉലപോലെയാണ്. ഉല ഇരുമ്പിലെ മ്ലേഛതയെ പുറംതള്ളുംപോലെ മദീന അതിലുള്ള ദുശിച്ചവരെ പുറംതള്ളുംവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أُسَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَشْرَفَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أُطُمٍ مِنْ آطَامِ الْمَدِينَةِ، فَقَالَ: "هَلْ تَرَوْنَ مَا أَرَى، إِنِّي لَأَرَى مَوَاقِعَ الْفِتَنِ خِلَالَ بُيُوتِكُمْ كَمَوَاقِعِ الْقَطْرِ". (خ)', 'ഉസാമ(റ): നബി(സ) മദീനയിലെ കുന്നുകളിൽ ഒന്നിൽ കയറിക്കൊണ്ട് ചോദിച്ചു: "ഞാൻ കാണുന്നത് നിങ്ങൾ കാണുന്നുണ്ടോ? മഴത്തുള്ളികൾ വീഴുന്ന ഇടങ്ങൾപോലെ നിങ്ങളുടെ വീടുകൾക്കിടയിൽ കുഴപ്പങ്ങൾ പൊട്ടിപ്പുറപ്പെടുന്ന ഇടങ്ങൾ ഞാനിതാ കാണുന്നു." (ബു)', 'أُسَامَةَ', 'ഉസാമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْمَدِينَةَ رُعْبُ الْمَسِيحِ الدَّجَّالِ، لَهَا يَوْمَئِذٍ سَبْعَةُ أَبْوَابٍ، عَلَى كُلِّ بَابٍ مَلَكَانِ". (خ)', 'അബൂബക്ർ(റ): നബി(സ) പറഞ്ഞു: "ലോകത്ത് ചുറ്റിസഞ്ചരിക്കുന്ന ദജ്ജാലിനെ സംബന്ധിച്ച ഭയം മദീനയെ ബാധിക്കുകയില്ല. അന്ന് മദീനക്ക് ഏഴ് കവാടങ്ങളുണ്ടായിരിക്കും. അതിൽ ഓരോ കവാടത്തിങ്കലും രണ്ടു മലക്കുകൾവീതം ഉണ്ടാകും." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്ർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى أَنْقَابِ الْمَدِينَةِ مَلَائِكَةٌ، لَا يَدْخُلُهَا الطَّاعُونُ وَلَا الدَّجَّالُ". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മദീനയുടെ പ്രവേശന കവാടങ്ങളിൽ മലക്കുകളുണ്ട്. പ്ലേഗോ ദജ്ജാലോ അതിൽ പ്രവേശിക്കുകയില്ല." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 527, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ مِنْ بَلَدٍ إِلَّا سَيَطَؤُهُ الدَّجَّالُ، إِلَّا مَكَّةَ وَالْمَدِينَةَ، لَيْسَ لَهُ مِنْ نِقَابِهَا نَقْبٌ إِلَّا عَلَيْهِ الْمَلَائِكَةُ صَافِّينَ يَحْرُسُونَهَا، ثُمَّ تَرْجُفُ الْمَدِينَةُ بِأَهْلِهَا ثَلَاثَ رَجَفَاتٍ، فَيُخْرِجُ اللهُ كُلَّ كَافِرٍ وَمُنَافِقٍ". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "മക്കയും മദീനയും ഒഴിച്ചുള്ള എല്ലാ നാടുകളിലും ദജ്ജാൽ കാല്കുത്തും. ആ രണ്ടു നാടുകളിലേക്കും അവൻ പ്രവേശിക്കുന്ന എല്ലാ കവാടങ്ങളിലും മലക്കുകൾ അണിയണിയായി കാവൽ നിൽക്കും. ശേഷം മദീന അതിന്റെ നിവാസികളോടുകൂടെ മൂന്നു പ്രാവശ്യത്തെ പ്രകമ്പനത്തിനു വിധേയമാകും. അങ്ങനെ (മദീനയിലെ) സത്യനിഷേധികളെയും കപടവിശ്വാസികളെയും അല്ലാഹു പുറത്താക്കും." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا حَدِيثًا طَوِيلًا عَنِ الدَّجَّالِ، فَكَانَ فِيمَا حَدَّثَنَا قَالَ: "يَأْتِي – وَهُوَ مُحَرَّمٌ عَلَيْهِ أَنْ يَدْخُلَ نِقَابَ الْمَدِينَةِ – فَيَنْتَهِي إِلَى بَعْضِ السِّبَاخِ الَّتِي تَلِي الْمَدِينَةَ، فَيَخْرُجُ إِلَيْهِ يَوْمَئِذٍ رَجُلٌ هُوَ خَيْرُ النَّاسِ – أَوْ: مِنْ خَيْرِ النَّاسِ – فَيَقُولُ لَهُ: أَشْهَدُ أَنَّكَ الدَّجَّالُ الَّذِي حَدَّثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثَهُ، فَيَقُولُ الدَّجَّالُ: أَرَأَيْتُمْ إِنْ قَتَلْتُ هَذَا ثُمَّ أَحْيَيْتُهُ، أَتَشُكُّونَ فِي الْأَمْرِ؟ فَيَقُولُونَ: لَا، قَالَ: فَيَقْتُلُهُ ثُمَّ يُحْيِيهِ، فَيَقُولُ حِينَ يُحْيِيهِ: وَاللهِ مَا كُنْتُ فِيكَ قَطُّ أَشَدَّ بَصِيرَةً مِنِّي الْآنَ، قَالَ: فَيُرِيدُ الدَّجَّالُ أَنْ يَقْتُلَهُ فَلَا يُسَلَّطُ عَلَيْهِ". قَالَ أَبُو إِسْحَقَ: يُقَالُ: إِنَّ هَذَا الرَّجُلَ هُوَ الْخَضِرُ عَلَيْهِ السَّلَامُ. (ق)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒരു ദിവസം ദജ്ജാലിനെക്കുറിച്ച് റസൂൽ(സ) ധാരാളമായി ഞങ്ങളോട് സംസാരിച്ചു. കൂട്ടത്തിൽ ഇങ്ങനെ പറഞ്ഞു: "അവൻ വരും - മദീനയിലേക്കുള്ള പ്രവേശന സ്ഥലങ്ങളിൽ പ്രവേശിക്കൽ അവന് നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കും - അങ്ങനെ മദീനക്കടുത്തുള്ള സസ്യങ്ങൾ മുളക്കാത്ത ഒരു സ്ഥലത്ത് വരെയെത്തും. അപ്പോൾ ജനങ്ങളിൽ വെച്ച് ഏറ്റവും നല്ല - അല്ലെങ്കിൽ: ജനങ്ങളിലെ നല്ലവരിൽപെട്ട - മനുഷ്യൻ അവന്റെയടുത്ത് ചെന്ന് പറയും: റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞുതന്നിട്ടുള്ള ദജ്ജാലാണ് നീ എന്ന് ഞാൻ സാക്ഷ്യംവഹിക്കുന്നു. അപ്പോൾ ദജ്ജാൽ പറയും: ഞാൻ ഇവനെ വധിച്ചതിന് ശേഷം ജീവിപ്പിച്ചാൽ എന്റെ കാര്യത്തിൽ നിങ്ങൾ സംശയിക്കുമോ? അവർ പറയും: ഇല്ല. അപ്പോൾ അവൻ അയാളെ കൊല്ലുകയും പിന്നെ ജീവിപ്പിക്കുകയും ചെയ്യും. തന്നെ ജീവിപ്പിക്കുമ്പോൾ അയാൾ അവനോട് പറയും: അല്ലാഹുവാണ, മുമ്പൊരിക്കലും നിന്റെ വിഷയത്തിൽ എനിക്ക് ഇതുപോലെ ഉൾകാഴ്ച ലഭിച്ചിട്ടില്ല¹. നബി(സ) പറയുന്നു: അപ്പോൾ ദജ്ജാൽ അയാളെ കൊല്ലാൻ ശ്രമിക്കും. പക്ഷേ, അയാളുടെ മേൽ ഒരു ആധിപത്യവും ദജ്ജാലിനുണ്ടാവുകയില്ല." അബൂഇസ്ഹാഖ്(റ) പറയുന്നു: നിശ്ചയം ഈ മനുഷ്യൻ ഖിള്ർ(അ) ആകുന്നു. (ബു,മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', '¹. നീ ദജ്ജാലാണെന്ന് എനിക്ക് കൂടുതൽ ബോധ്യമായിരിക്കുന്നു എന്നർത്ഥം.', null, array['ق']::text[], array['ബു','മു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَكِيدُ أَهْلَ الْمَدِينَةِ أَحَدٌ إِلَّا انْمَاعَ، كَمَا يَنْمَاعُ الْمِلْحُ فِي الْمَاءِ". (خ)', 'സഅ്ദ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മദീനക്കാരോട് ആര് കുതന്ത്രം പ്രയോഗിച്ചാലും ഉപ്പ് വെള്ളത്തിൽ അലിയുംപോലെ അവൻ അലിഞ്ഞുപോകാതിരിക്കില്ല." (ബു)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَرَادَ أَهْلَ هَذِهِ الْبَلْدَةِ بِسُوءٍ – يَعْنِي الْمَدِينَةَ – أَذَابَهُ اللهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ". (م،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ നാട്ടുകാരോട് - അതായത് മദീനക്കാരോട് - തിന്മചെയ്യാൻ ആരെങ്കിലും ഉദ്ദേശിച്ചാൽ ഉപ്പ് വെള്ളത്തിൽ അലിയുന്നതുപോലെ അല്ലാഹു അവനെ നശിപ്പിക്കുന്നതാണ്." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 528, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: مَرَّ بِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قُلْتُ لَهُ: كَيْفَ سَمِعْتَ أَبَاكَ يَذْكُرُ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى، قَالَ: قَالَ أَبِي: دَخَلْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ بَعْضِ نِسَائِهِ، فَقُلْتُ: يَا رَسُولَ اللهِ، أَيُّ الْمَسْجِدَيْنِ الَّذِي أُسِّسَ عَلَى التَّقْوَى؟ قَالَ: فَأَخَذَ كَفًّا مِنْ حَصْبَاءَ، فَضَرَبَ بِهِ الْأَرْضَ ثُمَّ قَالَ: "هُوَ مَسْجِدُكُمْ هَذَا" لِمَسْجِدِ الْمَدِينَةِ. قَالَ: فَقُلْتُ: أَشْهَدُ أَنِّي سَمِعْتُ أَبَاكَ هَكَذَا يَذْكُرُهُ. (م)', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ): എന്റെ സമീപത്തുകൂടെ അബ്ദുർറഹ്മാനുബ്നു അബീസഈദുൽഖുദ്രി(റ) നടന്നുപോയി. നിവേദകൻ പറയുന്നു: ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: ''ദൈവഭക്തിയിൽ അധിഷ്ടിതമായി നിർമ്മിക്കപ്പെട്ട പള്ളി'' (എന്ന് അല്ലാഹു നാമകരണം ചെയ്ത പള്ളി)യെ സംബന്ധിച്ച് താങ്കളുടെ പിതാവ് എന്തു പറയുന്നതായാണ് താങ്കൾ കേട്ടിട്ടുള്ളത്? അദ്ദേഹം പറഞ്ഞു: എന്നോട് എന്റെ പിതാവ് പറഞ്ഞു: റസൂൽ(സ) തന്റെ ഒരു പത്നിയുടെ വീട്ടിലായിരിക്കെ ഞാൻ അവിടുത്തെ സമീപത്തേക്ക് ചെന്നുകൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ? രണ്ടു പള്ളികളിൽ ''ദൈവഭക്തിയിൽ അധിഷ്ടിതമായി നിർമ്മിക്കപ്പെട്ട പള്ളി'' ഏതാണ്? നിവേദകൻ പറയുന്നു: അപ്പോൾ തിരുമേനി(സ) ഒരു പിടി ചെരലെടുക്കുകയും അത് ഭൂമിയിലേക്ക് എറിയുകയും ശേഷം ഇപ്രകാരം പറയുകയും ചെയ്തു: "അത് നിങ്ങളുടെ ഈ പള്ളിയാണ്." മദീനയിലെ പള്ളിയെ സംബന്ധിച്ചാണത് പറഞ്ഞത്. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: താങ്കളുടെ പിതാവ് അപ്രകാരം പറയുന്നത് നിശ്ചയം ഞാൻ കേട്ടിട്ടുണ്ടെന്നതിന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. (മു)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْتِي مَسْجِدَ قُبَاءٍ، رَاكِبًا وَمَاشِيًا، فَيُصَلِّي فِيهِ رَكْعَتَيْنِ. (ق،د،ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) നടന്നുകൊണ്ടും വഹനം കയറിക്കൊണ്ടുമെല്ലാം മസ്ജിദുൽഖുബാഇൽ വരികയും അവിടെവെച്ച് രണ്ടു റക്അത് നമസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يَأْتِي قُبَاءً كُلَّ سَبْتٍ، وَكَانَ يَقُولُ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْتِيهِ كُلَّ سَبْتٍ. (م)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം എല്ലാ ശനിയാഴ്ച ദിവസവും ഖുബാഇൽ വരുമായിരുന്നു. അദ്ദേഹം ഇപ്രകാരം പറയുകയും ചെയ്യുമായിരുന്നു: നബി(സ) എല്ലാ ശനിയാഴ്ച ദിവസവും ഖുബാഇൽ വരുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ: مَسْجِدِ الْحَرَامِ، وَمَسْجِدِي هَذَا، وَالْمَسْجِدِ الْأَقْصَى". (ق،د،ن،جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് പള്ളികളിലേക്കല്ലാതെ യാത്ര ചെയ്യാൻ പാടില്ല: മസ്ജിദുൽ ഹറാം, എന്റെ ഈ പള്ളി (മസ്ജിദുന്നബവി), മസ്ജിദുൽ അഖ്സാ എന്നിവയാണവ." (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
